-- Repeated queue reconciliation must not dirty unchanged metadata.
DROP TRIGGER lexicon_entries_update;
CREATE TRIGGER lexicon_entries_update AFTER UPDATE OF revision,missing,scope_excluded,kind,is_dir,event_json,source_id,parent ON entries WHEN OLD.revision IS NOT NEW.revision OR OLD.missing IS NOT NEW.missing OR OLD.scope_excluded IS NOT NEW.scope_excluded OR OLD.kind IS NOT NEW.kind OR OLD.is_dir IS NOT NEW.is_dir OR OLD.event_json IS NOT NEW.event_json OR OLD.source_id IS NOT NEW.source_id OR OLD.parent IS NOT NEW.parent BEGIN INSERT INTO lexicon_dirty VALUES(OLD.id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token;INSERT INTO lexicon_dirty VALUES(NEW.id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token; END;
DROP TRIGGER lexicon_analysis_update;
CREATE TRIGGER lexicon_analysis_update AFTER UPDATE OF revision,provider,version,data_json ON analysis WHEN OLD.revision IS NOT NEW.revision OR OLD.provider IS NOT NEW.provider OR OLD.version IS NOT NEW.version OR OLD.data_json IS NOT NEW.data_json BEGIN INSERT INTO lexicon_dirty VALUES(OLD.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token;INSERT INTO lexicon_dirty VALUES(NEW.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token; END;
