CREATE TRIGGER lexicon_metadata_update AFTER UPDATE OF field,layer,value_json,source_revision,stale,info_json ON metadata WHEN OLD.field IS NOT NEW.field OR OLD.layer IS NOT NEW.layer OR OLD.value_json IS NOT NEW.value_json OR OLD.source_revision IS NOT NEW.source_revision OR OLD.stale IS NOT NEW.stale OR OLD.info_json IS NOT NEW.info_json BEGIN INSERT INTO lexicon_dirty VALUES(OLD.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token;INSERT INTO lexicon_dirty VALUES(NEW.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token; END;
DROP TRIGGER lexicon_curation_update;
CREATE TRIGGER lexicon_curation_update AFTER UPDATE OF excluded ON curation WHEN OLD.excluded IS NOT NEW.excluded BEGIN INSERT INTO lexicon_dirty VALUES(OLD.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token;INSERT INTO lexicon_dirty VALUES(NEW.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token; END;
