CREATE TRIGGER lexicon_media_info_update AFTER UPDATE OF revision,data_json,updated ON media_info WHEN OLD.revision IS NOT NEW.revision OR OLD.data_json IS NOT NEW.data_json OR OLD.updated IS NOT NEW.updated BEGIN INSERT INTO lexicon_dirty VALUES(OLD.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token;INSERT INTO lexicon_dirty VALUES(NEW.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token; END;
DROP TRIGGER lexicon_media_jobs_update;
CREATE TRIGGER lexicon_media_jobs_update AFTER UPDATE OF revision,status ON media_jobs WHEN OLD.revision IS NOT NEW.revision OR OLD.status IS NOT NEW.status BEGIN INSERT INTO lexicon_dirty VALUES(OLD.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token;INSERT INTO lexicon_dirty VALUES(NEW.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token; END;
DROP TRIGGER lexicon_cache_files_update;
CREATE TRIGGER lexicon_cache_files_update AFTER UPDATE OF asset_id,revision,profile,path ON cache_files WHEN OLD.asset_id IS NOT NEW.asset_id OR OLD.revision IS NOT NEW.revision OR OLD.profile IS NOT NEW.profile OR OLD.path IS NOT NEW.path BEGIN INSERT INTO lexicon_dirty VALUES(OLD.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token;INSERT INTO lexicon_dirty VALUES(NEW.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token; END;
